//
// Conversion from semitones to frequency ratio.

#include "stmlib/dsp/units.h"

namespace stmlib {

/* extern */
// Beets: the literal tables lut_pitch_ratio_high[] / lut_pitch_ratio_low[]
// were replaced by this lossless encoding (generated by
// scripts/gen_pitch_tables.py from the upstream file; host/test_units.cc
// checks every bit against the upstream values).
//   high[i] bits = kHighBits[(i - 128) mod 12] + (floor((i - 128) / 12) << 23)
//   low[j] bits  = second-order integer prefix sums of kLowSecondDelta
//   entry 256    = 0.0f (implicit zero of the upstream 257-entry arrays)
static const uint32_t kHighBits[12] = {0x3f800000, 0x3f879c7d, 0x3f8facd6, 0x3f9837f0, 0x3fa14518, 0x3faadc08, 0x3fb504f3, 0x3fbfc887, 0x3fcb2ff5, 0x3fd744fd, 0x3fe411f0, 0x3ff1a1bf};
static const uint32_t kLowFirst = 0x3f800000;
static const int32_t kLowFirstDelta = 1893;
static const uint8_t kLowSecondDelta[64] = {0x99, 0x59, 0x66, 0x69, 0x59, 0xa6, 0x68, 0x99, 0x59, 0x66, 0x96, 0x99, 0x65, 0x66, 0x99, 0x99, 0x65, 0x96, 0x32, 0xa3, 0x65, 0x69, 0x99, 0x59, 0x66, 0x96, 0x99, 0x59, 0x66, 0x96, 0x32, 0x5a, 0xca, 0x68, 0x99, 0x59, 0xca, 0x68, 0x29, 0xa3, 0xa5, 0x8c, 0x96, 0x32, 0x5a, 0x66, 0x66, 0x99, 0x99, 0x65, 0x66, 0x96, 0x96, 0xa5, 0x65, 0x66, 0x96, 0x99, 0x59, 0x5a, 0x66, 0x69, 0x99, 0x09};

// Original python code
//
// TABLE_SIZE = 256
//
// ratio = numpy.arange(0, TABLE_SIZE) - 128
// ratio = 2 ** (ratio / 12.0)
// semitone = 2 ** (numpy.arange(0, TABLE_SIZE) / 256.0 / 12.0)
//
// lookup_tables.append(('pitch_ratio_high', ratio))
// lookup_tables.append(('pitch_ratio_low', semitone))

const float* lut_pitch_ratio_high;
const float* lut_pitch_ratio_low;

static inline float FloatFromBits(uint32_t b) {
  union { uint32_t u; float f; } c;
  c.u = b;
  return c.f;
}

void InitPitchRatioTables(float* storage) {
  float* high = storage;
  float* low = storage + 257;
  for (int i = 0; i < 256; ++i) {
    const int o = (i - 128 + 1200) / 12 - 100;  // floor division
    const int k = (i - 128) - 12 * o;
    high[i] = FloatFromBits(kHighBits[k] + uint32_t(int32_t(o) << 23));
  }
  uint32_t b = kLowFirst;
  int32_t d = kLowFirstDelta;
  low[0] = FloatFromBits(b);
  for (int j = 1; j < 256; ++j) {
    b += uint32_t(d);
    low[j] = FloatFromBits(b);
    if (j < 255) {
      d += int32_t((kLowSecondDelta[(j - 1) >> 2] >> (((j - 1) & 3) * 2)) & 3) - 1;
    }
  }
  high[256] = 0.0f;
  low[256] = 0.0f;
  lut_pitch_ratio_high = high;
  lut_pitch_ratio_low = low;
}

}  // namespace stmlib
